<?php $this->layout('default'); use Moves\Services\Helpdesk as H; use Moves\Support\CmsView as V; ?>
<form class="cms-card" method="post" action="/acao/quick-reply-save"><h2>Nova resposta rápida</h2><?= V::csrf() ?><?= V::field('Título', 'title', '', ['required' => true]) ?><?= V::field('Texto', 'body', '', ['type' => 'textarea', 'required' => true]) ?><button class="cms-btn-primary">Salvar</button></form>
<?php $rows = H::quickReplies(); if ($rows === []): ?><div class="cms-card"><?= V::empty('Nenhuma resposta rápida cadastrada.') ?></div><?php endif; foreach ($rows as $q): ?><details class="cms-card"><summary><?= V::e($q['title']) ?></summary><form method="post" action="/acao/quick-reply-save"><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $q['id'] ?>"><div class="cms-field"><label>Título<input name="title" value="<?= V::e($q['title']) ?>"></label></div><div class="cms-field"><label>Texto<textarea name="body" rows="4"><?= V::e($q['body']) ?></textarea></label></div><button class="cms-btn-primary">Salvar</button></form><?= V::actionButton('quick-reply-delete', 'Excluir', ['id' => $q['id']], 'cms-btn-danger', 'Excluir esta resposta?') ?></details><?php endforeach; ?>
